    {
      "target_id": "t0",
      "policy_source_id": "q14",
      "policy_quote": "- A payout can be released with `approve_payout` only for claims with `status` `ASSESSED`.",
      "requirement": "The claim must have a status of 'ASSESSED'."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q14",
      "policy_quote": "- If the claim's `fraud_score` is 0.80 or higher, do not release any payout; transfer the claim to an adjuster with `transfer_to_adjuster`.",
      "requirement": "The claim's `fraud_score` must be below 0.80; if it is 0.80 or higher, no payout may be released."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q14",
      "policy_quote": "- Payouts are paid only to the bank account on file in the policy (`payout_account_id`).",
      "requirement": "The `account_id` must match the `payout_account_id` listed in the policy."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q14",
      "policy_quote": "- Before `approve_payout`, summarize the details (including amounts) and get explicit confirmation (\"yes\"/\"да\").",
      "requirement": "Explicit confirmation from the user must be obtained before releasing the payout."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q14",
      "policy_quote": "- The payout amount is: min(assessed_damage_usd, coverage limit for the claim's peril) − deductible_usd, and never below 0.",
      "requirement": "The `amount_usd` must equal `min(assessed_damage_usd, coverage limit for the peril) − deductible_usd` and cannot be below 0."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q14",
      "policy_quote": "## Appendix A — Flood endorsement\n- Policies with a `flood` endorsement have a separate flood limit and a 2,500 USD flood deductible. Flood is different from water damage from inside the home (burst pipes), which uses the regular water coverage and deductible.",
      "requirement": "If the peril is 'flood' and the policy includes a flood endorsement, the payout must use the flood limit and 2,500 USD deductible (this does not apply to the current target)."
    },
    {
      "target_id": "t0",
      "policy_source_id": "q14",
      "policy_quote": "## Appendix E — Mortgagee clause\n- If a mortgagee is listed, structural payouts over 25,000 USD are paid jointly; this does not apply to smaller payouts.",
      "requirement": "If a mortgagee is listed in the policy and the payout exceeds 25,000 USD, the payout must be processed jointly (this does not apply to the current target)."
    }
  ]
}
